import * as React from "react"
import { useMemo } from "react"
import { motion } from "framer-motion"
import { containerStyles } from "https://framer.com/m/framer/default-utils.js@^0.45.0"
import {
    emptyStateStyle,
    stateParagraphStyle,
    stateTitleStyle,
} from "https://framer.com/m/framer/integrations-styles.js@0.2.0"
import {
    PropertyControls,
    addPropertyControls,
    ControlType,
    RenderTarget,
} from "framer"

const soundCloudRegex =
    /^(https?:\/\/(?:www\.)?soundcloud\.com\/[^\/]+\/[^\/]+)/

/**
 * SOUNDCLOUD
 *
 * @framerIntrinsicWidth 500
 * @framerIntrinsicHeight 300
 *
 * @framerSupportedLayoutWidth fixed
 * @framerSupportedLayoutHeight fixed
 */
export function SoundCloud({
    theme,
    showComments,
    showUser,
    visual,
    showReposts,
    showTeaser,
    autoplay,
    playOnCanvas,
    showRelated,
    color,
    url,
    style,
    ...props
}) {
    const src = useMemo(() => {
        const [, validUrl] = url.match(soundCloudRegex) ?? [null, null]

        if (!validUrl) return null

        const isCanvas = RenderTarget.current() === RenderTarget.canvas

        const parameters = new URLSearchParams(new URL(url).search)
        parameters.set("url", validUrl)
        parameters.set("show_comments", showComments)
        parameters.set("show_user", showUser)
        parameters.set("visual", visual)
        parameters.set("show_reposts", showReposts)
        parameters.set(
            "auto_play",
            isCanvas && !playOnCanvas ? false : autoplay
        )
        parameters.set("show_teaser", showTeaser)
        parameters.set("hide_related", (!showRelated).toString())
        parameters.set("color", color)

        const finalURL = new URL("https://w.soundcloud.com/player")
        finalURL.search = parameters.toString()
        return finalURL.toString()
    }, [
        url,
        showComments,
        showRelated,
        showUser,
        visual,
        showReposts,
        autoplay,
        playOnCanvas,
        showTeaser,
        color,
    ])

    return url && src ? (
        <iframe
            style={{ height: "100%", width: "100%", ...style }}
            frameBorder={0}
            allow="autoplay"
            scrolling="no"
            src={src}
        />
    ) : (
        <motion.div
            style={{
                ...emptyStateStyle,
                ...style,
            }}
            {...props}
        >
            <h1 style={stateTitleStyle}>SoundCloud</h1>
            {url ? (
                <p style={stateParagraphStyle}>
                    This track URL doesn’t seem correct.
                </p>
            ) : (
                <p style={stateParagraphStyle}>
                    Set a track URL in the Properties.
                </p>
            )}
        </motion.div>
    )
}

SoundCloud.defaultProps = {
    url: "https://soundcloud.com/flume/flume-lose-it-feat-vic-mensa",
    width: 300,
    height: 300,
    showComments: false,
    showUser: true,
    showReposts: false,
    showTeaser: true,
    visual: true,
    autoplay: false,
    playOnCanvas: false,
    showRelated: true,
    color: "#f50",
}

addPropertyControls(SoundCloud, {
    url: { type: ControlType.String, title: "URL" },
    visual: {
        type: ControlType.Boolean,
        title: "Type",
        enabledTitle: "Visual",
        disabledTitle: "Classic",
    },
    color: {
        type: ControlType.Color,
        title: "Color",
    },
    autoplay: {
        title: "Autoplay",
        type: ControlType.Boolean,
        enabledTitle: "Play",
        disabledTitle: "Pause",
    },
    playOnCanvas: {
        title: "On Canvas",
        type: ControlType.Boolean,
        enabledTitle: "Play",
        disabledTitle: "Pause",
    },
    showComments: {
        type: ControlType.Boolean,
        title: "Comments",
        enabledTitle: "Show",
        disabledTitle: "Hide",
    },
    showUser: {
        type: ControlType.Boolean,
        title: "User",
        enabledTitle: "Show",
        disabledTitle: "Hide",
    },
    showReposts: {
        type: ControlType.Boolean,
        title: "Reposts",
        enabledTitle: "Show",
        disabledTitle: "Hide",
    },
    showTeaser: {
        type: ControlType.Boolean,
        title: "Teaser",
        enabledTitle: "Show",
        disabledTitle: "Hide",
    },
    showRelated: {
        type: ControlType.Boolean,
        title: "Related",
        enabledTitle: "Show",
        disabledTitle: "Hide",
    },
})
